import json
codes=[]; invalid=[]
with open('log.jsonl','rb') as f:
    data=f.read().decode('utf-8')
for i,line in enumerate(data.split('\n'),1):
    if line.strip()=='':
        continue
    try:
        obj=json.loads(line)
